import base64
import io
import numpy as np
from evaluator.base_agent import BaseAgent

# PASTE THE STRING FROM STEP 1 HERE
WEIGHTS_BASE64 = ""
 

class MyAgent(BaseAgent):
    def __init__(self):
        super().__init__()
        try:
            # Load NumPy weights from Base64
            weights_bytes = base64.b64decode(WEIGHTS_BASE64)
            with np.load(io.BytesIO(weights_bytes)) as data:
                # Feature Layers
                self.wf1, self.bf1 = data['feature_layer.0.weight'], data['feature_layer.0.bias']
                self.wf2, self.bf2 = data['feature_layer.2.weight'], data['feature_layer.2.bias']
                # Value Stream
                self.wv1, self.bv1 = data['value_stream.0.weight'], data['value_stream.0.bias']
                self.wv2, self.bv2 = data['value_stream.2.weight'], data['value_stream.2.bias']
                # Advantage Stream
                self.wa1, self.ba1 = data['advantage_stream.0.weight'], data['advantage_stream.0.bias']
                self.wa2, self.ba2 = data['advantage_stream.2.weight'], data['advantage_stream.2.bias']
            print("✅ MyAgent: Dueling NumPy weights loaded (Torch-free!)")
        except Exception as e:
            print(f"❌ MyAgent: Failed to load: {e}")

    def relu(self, x):
        return np.maximum(0, x)

    def preprocess_obs(self, observation, goal_pos=(64, 127)):
        # EXACT same 10-feature logic
        obs = observation[:6].copy()
        obs[0:2] /= 128.0
        obs[2:4] /= 8.0
        obs[4:6] /= 10.0
        dx = (goal_pos[0] - observation[0]) / 128.0
        dy = (goal_pos[1] - observation[1]) / 128.0
        dist = np.sqrt(dx**2 + dy**2)
        angle = np.arctan2(dy, dx) / np.pi 
        return np.concatenate([obs, [dx, dy, dist, angle]]).astype(np.float32)

    def act(self, observation):
        # 1. Preprocess
        x = self.preprocess_obs(observation)

        # 2. Forward Pass: Feature Extractor
        # We use .T because PyTorch stores as (out, in), NumPy needs (in, out)
        h1 = self.relu(np.dot(x, self.wf1.T) + self.bf1)
        h2 = self.relu(np.dot(h1, self.wf2.T) + self.bf2)

        # 3. Forward Pass: Value Stream
        hv = self.relu(np.dot(h2, self.wv1.T) + self.bv1)
        v = np.dot(hv, self.wv2.T) + self.bv2

        # 4. Forward Pass: Advantage Stream
        ha = self.relu(np.dot(h2, self.wa1.T) + self.ba1)
        a = np.dot(ha, self.wa2.T) + self.ba2

        # 5. Dueling Aggregation: Q = V + (A - mean(A))
        q_values = v + (a - np.mean(a))

        return int(np.argmax(q_values))

    def reset(self): pass
    def seed(self, seed=None):
        if seed is not None: np.random.seed(seed)